import 'package:cloud_firestore/cloud_firestore.dart';
enum CallStatus { ringing, accepted, rejected, missed, ended }
class CallModel { const CallModel({required this.id,required this.conversationId,required this.callerId,required this.recipientId,required this.status,required this.createdAt,this.providerRoomId}); final String id,conversationId,callerId,recipientId; final CallStatus status; final DateTime createdAt; final String? providerRoomId; factory CallModel.fromMap(String id,Map<String,dynamic> map)=>CallModel(id:id,conversationId:map['conversationId'] as String? ?? '',callerId:map['callerId'] as String? ?? '',recipientId:map['recipientId'] as String? ?? '',status:CallStatus.values.firstWhere((item)=>item.name==map['status'],orElse:()=>CallStatus.ringing),createdAt:(map['createdAt'] as Timestamp?)?.toDate() ?? DateTime.now(),providerRoomId:map['providerRoomId'] as String?); Map<String,Object?> toMap()=>{'conversationId':conversationId,'callerId':callerId,'recipientId':recipientId,'status':status.name,'createdAt':Timestamp.fromDate(createdAt),'providerRoomId':providerRoomId}; }
